def replace_paragraph(paragraph, text):
    if not paragraph.runs:
        paragraph.add_run(text)
        return
    paragraph.runs[0].text = text
    for run in paragraph.runs[1:]:
        run.text = ""

doc = Document(PATH)
for p in doc.paragraphs:
    if p.text in REPL:
        replace_paragraph(p, REPL[p.text])

doc.save(PATH)
